import {CONTENT_MODES,planningOf,planningInputKey,selectedPlan} from './planning.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const input=(label,key,value,area=false)=>`<label class="planning-field"><span>${label}</span>${area?`<textarea rows="3" data-planning-field="${key}">${esc(value)}</textarea>`:`<input data-planning-field="${key}" value="${esc(value)}">`}</label>`;
export function planningSummary(p){const c=selectedPlan(p);if(!c)return '';return `<aside class="planning-summary"><div><span class="planning-kicker">本期方向 · ${esc(CONTENT_MODES[p.planning.mode].name)}</span><strong>${esc(c.title)}</strong><p>${esc(c.benefit)}</p></div><button class="btn text small" data-action="content-tab" data-tab="planning">调整策划</button></aside>`;}
export function planningView(p,prefs){const x=planningOf(p,prefs),key=planningInputKey(x),selected=selectedPlan(p);return `<div class="planning-layout"><section class="panel planning-input"><span class="planning-kicker">01 / 从一个想法开始</span><h2>这一期想聊什么？</h2>${input('你的想法','idea',x.idea,true)}<div class="planning-label">希望读者看完能……</div><div class="planning-modes">${Object.entries(CONTENT_MODES).map(([id,m])=>`<button class="planning-mode ${x.mode===id?'active':''}" data-action="planning-mode" data-mode="${id}" aria-pressed="${x.mode===id}"><b>${m.name}</b><small>${m.description}</small></button>`).join('')}</div><details class="planning-preferences"><summary>本期偏好 <span>沿用账号默认，也可以单独调整</span></summary>${input('给谁看','audience',x.audience)}${input('讲解口吻','tone',x.tone)}${input('视觉方向','visualDirection',x.visualDirection,true)}<label class="planning-checkbox"><input type="checkbox" data-planning-field="personalCase" ${x.personalCase?'checked':''}> 使用有真实材料的个人案例</label></details><div class="planning-handoff"><button class="btn primary" data-action="planning-task" ${x.idea.trim()?'':'disabled'}>复制策划任务</button><p>发到当前 Codex 对话。策划结果会回到这里，先选方向，再写正文。</p></div><button class="btn text small" data-action="planning-import">粘贴策划结果 JSON</button><button class="btn text small" data-action="planning-refresh">刷新策划结果</button></section><section class="planning-results"><div class="planning-results-heading"><span class="planning-kicker">02 / 找到适合这一期的角度</span><h2>${selected?'这个方向，已经选定。':'先比较方向，再展开内容。'}</h2><p>选择会更新本期简报；已有正文保留，内容需要重新确认。</p></div>${x.candidates.length?`<div class="planning-candidates">${x.candidates.map((c,i)=>{const stale=c.inputFingerprint!==key,chosen=selected?.id===c.id;return `<article class="planning-candidate ${chosen?'chosen':''}"><div class="row between"><span class="planning-number">方向 ${String(i+1).padStart(2,'0')}</span><span class="planning-state">${stale?'输入已变化':chosen?'已选方向':'待选择'}</span></div><h3>${esc(c.title)}</h3>${c.reason?`<p class="planning-reason">${esc(c.reason)}</p>`:''}<dl><dt>给谁看</dt><dd>${esc(c.audience||x.audience)}</dd><dt>看完获得什么</dt><dd>${esc(c.benefit)}</dd></dl><div class="planning-outline"><b>简短大纲</b><ol>${c.outline.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></div><details><summary>例子与依据</summary><ul>${c.evidence.map(t=>`<li>${esc(t)}</li>`).join('')||'<li>创作前核实必要事实。</li>'}</ul></details><button class="btn ${chosen?'secondary':'primary'}" data-action="planning-select" data-candidate="${esc(c.id)}" ${stale||chosen?'disabled':''}>${chosen?'已选定这个方向':'选定这个方向'}</button></article>`;}).join('')}</div>`:`<div class="planning-empty"><span class="planning-empty-mark">“</span><h3>先想清楚，讲哪一件事。</h3><p>这里会展示标题、读者收益和简短大纲。<br>这一轮只做策划，暂时不用逐张写图。</p></div>`}${selected?`<div class="planning-next"><button class="btn primary" data-action="creation-request">复制正文创作任务</button><button class="btn secondary" data-action="content-tab" data-tab="body">查看 / 编辑正文</button></div>`:'<button class="btn text small" data-action="content-tab" data-tab="body">已有清晰方向？直接编辑正文</button>'}</section></div>`;}
export function preferencesView(prefs){const field=(label,key,value,help)=>`<label class="preferences-field"><span>${label}</span><textarea rows="2" data-preference="${key}">${esc(value)}</textarea><small>${help}</small></label>`;return `<div class="page-heading"><div><div class="eyebrow">ACCOUNT NOTES</div><h1>让每一期，都从熟悉的方向开始。</h1><p>保存账号的常用偏好，新建时带入；每一期仍然可以单独调整。</p></div></div><form class="preferences-form panel" id="account-preferences-form"><div class="preferences-grid">${field('主要给谁看','audience',prefs.audience,'写具体一点，例如：刚接触 AI 的小白。')}${field('平时怎么讲','tone',prefs.tone,'口吻、术语解释与文字习惯。')}<label class="preferences-field"><span>默认内容方式</span><select data-preference="depth">${Object.entries(CONTENT_MODES).map(([id,m])=>`<option value="${id}" ${prefs.depth===id?'selected':''}>${m.name}</option>`).join('')}</select><small>这是起点，不是每一期的固定要求。</small></label>${field('常用视觉方向','visualDirection',prefs.visualDirection,'封面与内页可以分别设计，不要求固定模板。')}</div><label class="planning-checkbox"><input type="checkbox" data-preference="personalCase" ${prefs.personalCase?'checked':''}> 默认允许使用有真实材料的个人案例</label><div class="action-bar"><span class="small muted" data-preferences-status>保存只影响之后新建的内容，不改写旧稿。</span><button type="button" class="btn primary" data-action="preferences-save">保存账号偏好</button></div></form>`;}
